(()=>{const e="/blog/pages/child/";fetch("/blog/pages/child/manifest.json",{cache:"no-store"}).then(e=>{if(!e.ok)throw new Error(`Child blog manifest: ${e.status}`);return e.json()}).then(s=>{window.BLOG_DISCOVERY_CONFIG=Object.freeze({sourceDir:e,posts:Object.freeze((s.files||[]).map(s=>`${e}${s}`)),pinned:Object.freeze((s.pinned||[]).map(s=>`${e}${s}`)),mostSearched:Object.freeze((s.mostSearched||[]).map(s=>`${e}${s}`)),symptoms:Object.freeze(s.symptoms||[]),clusters:Object.freeze(s.clusters||[])}),window.dispatchEvent(new CustomEvent("blogConfigLoaded"))}).catch(()=>{window.BLOG_DISCOVERY_CONFIG={sourceDir:e,posts:["../../../sleep-and-autism-guide-indian-parents/","early-signs-of-autism.html","school-concerns-and-adhd.html","sensory-overload-at-home.html","speech-delay-red-flags.html"].map(s=>`${e}${s}`),pinned:[],mostSearched:[],symptoms:[],clusters:[]},window.dispatchEvent(new CustomEvent("blogConfigLoaded"))})})();